/* @lc app=leetcode id=2166 lang=kotlin */ class Bitset(val size: Int, val a: BooleanArray = BooleanArray(size), val st: IntArray = IntArray(2)) { override fun toString(): String = (0 until size).joinToString("") { if (v(it)) "1" else "0" } fun v(i: Int) = a[i] != (st[0] == 1) fun tg(i: Int, d: Int) = a.set(i, !a[i]).let { st[1] += d } fun fix(idx: Int) { if (!v(idx)) tg(idx, 1) } fun unfix(idx: Int) { if (v(idx)) tg(idx, -1) } fun flip() = st[0].let { st[0] = 1 - it }.let { st[1] = size - st[1] } fun all(): Boolean = st[1] == size fun one(): Boolean = st[1] > 0 fun count(): Int = st[1] }